func (q *Queries) LockCompanyGroupForChange(ctx context.Context, arg LockCompanyGroupForChangeParams) (CompanyGroup, error) {
	row := q.db.QueryRow(ctx, lockCompanyGroupForChange, arg.CompanyID, arg.GroupID)
	var i CompanyGroup
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.Name,
		&i.Description,
		&i.CreatedByUserID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
	)
	return i, err
}

