const updateCompanyGroup = `-- name: UpdateCompanyGroup :one
UPDATE company_groups
SET name = $1::text,
    description = $2::text,
    version = company_groups.version + 1,
    updated_at = clock_timestamp()
WHERE company_groups.company_id = $3::uuid
  AND company_groups.id = $4::uuid
  AND company_groups.version = $5::bigint
RETURNING id, company_id, name, description, created_by_user_id, created_at, updated_at, version
`

type UpdateCompanyGroupParams struct {
	Name            string    `json:"name"`
	Description     string    `json:"description"`
	CompanyID       uuid.UUID `json:"company_id"`
	GroupID         uuid.UUID `json:"group_id"`
	ExpectedVersion int64     `json:"expected_version"`
}

// Renames or redescribes the Group against the revision the caller read; no
// row means the revision moved.
func (q *Queries) UpdateCompanyGroup(ctx context.Context, arg UpdateCompanyGroupParams) (CompanyGroup, error) {
	row := q.db.QueryRow(ctx, updateCompanyGroup,
		arg.Name,
		arg.Description,
		arg.CompanyID,
		arg.GroupID,
		arg.ExpectedVersion,
	)
	var i CompanyGroup
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.Name,
		&i.Description,
		&i.CreatedByUserID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
	)
	return i, err
}
